    "ArcPad's $ARCIRCLE tab and foci trade the same on-chain curve, so the price is the same on both. Arc uses USDC for gas, so USDC is all you need.": "ArcPad 的 $ARCIRCLE 标签页和 foci 交易的是同一条链上曲线，所以两边价格相同。Arc 用 USDC 支付 Gas，所以只需要 USDC。",
