    "On ArcPad's $ARCIRCLE tab or on foci. Both trade the same bonding curve, so the price and the liquidity are the same.": "在 ArcPad 的 $ARCIRCLE 标签页或 foci 上。两者交易的是同一条联合曲线，所以价格和流动性相同。",
    "What happens at graduation?": "毕业时会发生什么？",
    "When the real USDC in the curve reaches its graduation threshold, trading moves from the curve to a DEX pool with that liquidity. The progress above is read live from the curve.": "当曲线中的真实 USDC 达到毕业门槛时，交易会带着这些流动性从曲线转移到 DEX 池。上方进度实时读取自曲线。",
    "Is there a team allocation?": "有团队份额吗？",
    "No. $ARCIRCLE launched with 100% of its 1,000,000,000 supply in the public curve. The supply split above shows where it sits today.": "没有。$ARCIRCLE 发射时 1,000,000,000 的供应 100% 放在公开曲线中。上方的供应分布显示了它现在的位置。",
    "What is the 2% creator tax?": "2% 创建者税是什么？",
