    "$ARCIRCLE is relaunching": "$ARCIRCLE 正在重新发行",
    "The core coin of ARCIRCLE PAD is getting a fresh launch. Until it goes live there is no official contract, price or chart — the new contract address will be posted here and on": "ARCIRCLE PAD 的核心币即将重新发行。上线前没有官方合约、价格或图表——新合约地址会在上线的那一刻公布在这里以及",
