    "$ARCIRCLE is relaunching.": "$ARCIRCLE 正在重新发行。",
    "There is no official contract, price or chart until the new launch goes live. The contract address will be posted on this page and by": "新发行上线前没有官方合约、价格或图表。合约地址将公布在本页以及",
    "— only trust the address published there.": "——只信任在那里公布的地址。",
    "There isn't one yet — $ARCIRCLE is relaunching. The new contract address will be posted on this page and by": "还没有——$ARCIRCLE 正在重新发行。新合约地址将在上线时公布在本页以及",
    "when it goes live. Don't trust addresses from anywhere else.": "上线时公布。不要相信其他来源的地址。",
    "Not yet. Join the launch alerts on Telegram (": "还不能买。加入 Telegram 上线提醒（",
    ") to hear the moment it goes live.": "），上线第一时间通知你。",
    "Not live yet — $ARCIRCLE is relaunching": "尚未上线——$ARCIRCLE 正在重新发行",
    "Starts when $ARCIRCLE is live": "$ARCIRCLE 上线后开始",
    "$ARCIRCLE is relaunching — nothing to hold yet": "$ARCIRCLE 正在重新发行——暂时无法持有",
    "Starts counting when $ARCIRCLE is live": "$ARCIRCLE 上线后开始计算",
    "Every launch gets a real Uniswap v4 pool in the same transaction — paired with USDC, Arc's own native currency, or with any Arc token you choose.": "每次发射都会在同一笔交易中获得真正的 Uniswap v4 池——与 Arc 原生货币 USDC 或你选择的任意 Arc 代币配对。",
    "$ARCIRCLE market": "$ARCIRCLE 市场",
    "Chart & pool": "图表与池",
    "Chart ↗": "图表 ↗",
    "Creator fee": "创作者费用",
    "Full chart ↗": "完整图表 ↗",
    "In the pool": "池中",
    "Is the liquidity locked?": "流动性锁定了吗？",
    "Launch & trade": "发射与交易",
    "Launch fees + $ARCIRCLE creator fee, in USDC": "发射费 + $ARCIRCLE 创作者费用，以 USDC 计",
    "Launch fees, ArcPad's platform allocation and trading fees, CirclePad's raise share, and $ARCIRCLE's own creator fee flow in.": "发射费、ArcPad 的平台分配与交易手续费、CirclePad 的募资分成，以及 $ARCIRCLE 自身的创作者费用都会流入。",
    "Launch fees, trading fees, raise shares and $ARCIRCLE's own creator fee all flow into the same flywheel.": "发射费、交易手续费、募资分成和 $ARCIRCLE 自身的创作者费用全部流入同一个飞轮。",
    "Launchpad": "发射平台",
    "Liquidity lock": "流动性锁定",
    "Loading chart…": "正在加载图表…",
