    "Your USDC goes straight to Circle's CCTP contracts — ARCIRCLE PAD never holds it and takes no fee. Fees are Circle's, deducted from the amount you send; you only pay gas on the chain you send from.": "你的 USDC 直接进入 Circle 的 CCTP 合约——ARCIRCLE PAD 从不持有资金，也不收取任何费用。费用由 Circle 收取，从发送金额中扣除；你只需在发送链上支付 Gas。",
