    "Owner powers only matter while someone holds them — after ownership is renounced they show as notes.": "所有者权限只有在有人持有时才有意义——放弃所有权后会显示为备注。",
    "In pool": "池中",
    "Top 10 wallets": "前 10 个钱包",
    "Largest wallets": "最大钱包",
