    "No contract at this address": "该地址没有合约",
    "Nothing is deployed here on Arc — it isn't a token.": "Arc 上此处没有部署任何东西——它不是代币。",
    "Not a standard token": "不是标准代币",
    "It doesn't answer the basic ERC-20 calls (name, symbol, decimals, supply).": "它不响应基本的 ERC-20 调用（名称、符号、小数位、供应量）。",
    "Standard ERC-20 token": "标准 ERC-20 代币",
    "Upgradeable proxy": "可升级代理",
    "Its code lives behind a beacon and can be switched to new code.": "其代码位于信标之后，可以切换为新代码。",
    "Fixed code": "代码固定",
    "Not a proxy — the code you see can't be swapped out.": "不是代理——你看到的代码无法被替换。",
    "ARCIRCLE PAD core coin": "ARCIRCLE PAD 核心币",
    "$ARCIRCLE, launched on Argus — one pool, supply in a single locked position.": "$ARCIRCLE，在 Argus 发行——一个池子，供应量在一个锁定仓位中。",
    "Launched on ArcPad": "在 ArcPad 发行",
    "The standard ArcPad token, launched through the ArcPad factory with its pool created in the same transaction.": "标准 ArcPad 代币，通过 ArcPad 工厂发行，池子在同一笔交易中创建。",
    "Not an ArcPad launch": "非 ArcPad 发行",
    "Launched somewhere else, so every check below is the generic one.": "在其他地方发行，所以下面都是通用检查。",
    "No owner": "无所有者",
    "The contract has no owner function — there's no admin wallet to call anything.": "合约没有所有者函数——没有可以调用任何功能的管理员钱包。",
    "Ownership renounced": "已放弃所有权",
    "The owner is the zero/dead address, so owner-only functions can't be called.": "所有者是零地址/销毁地址，因此无法调用仅限所有者的函数。",
    "Owned by a contract": "由合约持有",
    "Owned by a wallet": "由钱包持有",
