    "Often a multisig or timelock — check who controls it.": "通常是多签或时间锁——请确认由谁控制。",
    "One wallet can still call owner-only functions.": "一个钱包仍可调用仅限所有者的函数。",
    "Role-based permissions": "基于角色的权限",
