    "Transfers resumed": "转账已恢复",
    "Hook:": "钩子：",
    "Is it a standard token? Can its code be swapped out? Was it launched on ArcPad or Argus?": "是标准代币吗？代码能否被替换？是否在 ArcPad 或 Argus 发行？",
    "A dry-run buy, sell and transfer — does it go through, and how much tax is taken?": "模拟一次买入、卖出和转账——能否成功，被扣多少税？",
    "Where it trades, how deep the pool is, how old it is, and whether people actually sell.": "在哪里交易、池子有多深、存在多久、是否真的有人卖出。",
    "How spread out the supply is, who deployed it and what they still hold.": "供应量有多分散、谁部署的、他们还持有多少。",
    "Mints after launch, ownership changes, pauses and big moves — from the token's own log.": "发行后的增发、所有权变更、暂停和大额转移——来自代币自身的记录。",
    "Holder growth over time": "持有人随时间的增长",
    "Watch alerts on Telegram": "Telegram 关注提醒",
    "A public scan API for other Arc apps": "供其他 Arc 应用使用的公开扫描 API",
    "Reads Arc directly — the buy and sell checks are dry runs, nothing is signed or spent — plus Dexscreener for market data. An automated check, not advice: a clean scan can't rule out every risk, and a warning doesn't always mean a scam.": "直接读取 Arc——买卖检查是模拟运行，不签名也不花钱——市场数据来自 Dexscreener。这是自动检查，不是投资建议：结果干净不代表没有风险，出现警告也不一定是骗局。",
    "Launched on Argus": "在 Argus 发行",
    "Launched through an Argus portal: a Uniswap v4 pool with the supply in one locked position.": "通过 Argus 门户发行：一个 Uniswap v4 池，供应量在一个锁定仓位中。",
    "Not a launchpad token": "非发行平台代币",
    "Not launched through ArcPad or Argus, so every check below is the generic one.": "不是通过 ArcPad 或 Argus 发行，所以下面都是通用检查。",
    "No trade simulation": "无交易模拟",
    "There was no holder the dry run could act as.": "没有可用于模拟的持有人。",
    "Trade simulation unavailable": "无法进行交易模拟",
    "The Arc RPC didn't accept the dry run, so buying and selling weren't simulated.": "Arc RPC 不接受模拟调用，因此未能模拟买卖。",
    "Trades in its ArcPad pool": "在其 ArcPad 池中交易",
    "Trades in its Argus pool": "在其 Argus 池中交易",
    "A Uniswap v4 pool created at launch, its liquidity locked for good — read from the chain because Dexscreener hasn't listed it yet.": "发行时创建的 Uniswap v4 池，流动性永久锁定——Dexscreener 尚未收录，直接从链上读取。",
    "A Uniswap v4 pool created at launch — read from the chain because Dexscreener hasn't listed it yet.": "发行时创建的 Uniswap v4 池——Dexscreener 尚未收录，直接从链上读取。",
    "Deployer still holds tokens": "部署者仍持有代币",
    "Deployer holds none": "部署者未持有",
    "The wallet that created the token has passed on everything it minted.": "创建代币的钱包已转出其铸造的全部代币。",
    "Minted after launch": "发行后增发",
    "No mints after launch": "发行后无增发",
    "Every token that exists was minted when it was created.": "现存的所有代币都在创建时铸造。",
    "Renounced on-chain": "链上已放弃所有权",
    "Ownership changed hands": "所有权已转手",
    "Has been paused before": "曾被暂停",
    "Code was upgraded": "代码已升级",
    "Ownership went to the zero address.": "所有权已转至零地址。",
    "Set by Argus at launch and fixed in its pool hook; 90% of it goes to the creator.": "由 Argus 在发行时设定并固定在池钩子中；其中 90% 归创建者。",
    "Set by Argus at launch and fixed in its pool hook.": "由 Argus 在发行时设定并固定在池钩子中。",
    "Selling fails": "卖出失败",
    "Buying fails": "买入失败",
    "Sending fails": "转账失败",
    "Selling works": "可以卖出",
    "Buying works": "可以买入",
    "Sending works": "可以转账",
    "ArcPad's 1% pool fee, taken on every buy and sell.": "ArcPad 1% 池手续费，每次买卖都会收取。",
    "A standard token answers name, symbol, decimals and supply the same way wallets and exchanges expect.": "标准代币会按钱包和交易所预期的方式返回名称、符号、小数位和供应量。",
    "A proxy keeps its logic in another contract that can be swapped. Whoever controls the proxy can change how the token behaves.": "代理把逻辑放在另一个可替换的合约里。控制代理的人可以改变代币的行为。",
    "Tokens from a known launchpad follow a fixed template, so there is less room for hidden tricks.": "知名发行平台的代币遵循固定模板，隐藏手脚的空间更小。",
    "The owner can call owner-only functions. Renounced ownership means nobody can any more.": "所有者可以调用仅限所有者的函数。放弃所有权后就没有人能调用了。",
    "With role-based permissions several wallets can hold admin rights, even without an owner.": "使用基于角色的权限时，即使没有所有者，也可能有多个钱包持有管理权限。",
    "Found by reading the function list in the contract's code. It shows what the code allows, not whether it has been used.": "通过读取合约代码中的函数列表发现。它表示代码允许什么，而不是是否已被使用。",
    "The scanner pretends to be a real holder and sends a little in a dry run — nothing is signed or spent — to see whether it arrives and how much is taken.": "扫描器模拟一位真实持有人发送少量代币——不签名也不花钱——看是否到账、被扣多少。",
    "Taxes or fees charged on every trade go to the creator or the platform.": "每笔交易收取的税费归创建者或平台。",
    "Without a pool with enough money in it you may not be able to sell at a fair price.": "如果没有资金充足的池子，你可能无法以合理价格卖出。",
    "Liquidity is how much money sits in the pool. Thin pools move a lot on small trades.": "流动性是池中的资金量。浅池在小额交易时也会大幅波动。",
    "New pools have little history, which is when most rug pulls happen.": "新池子历史很短，而大多数跑路正发生在这个阶段。",
    "A token that is bought a lot but never sold is a classic sign that selling is blocked.": "大量买入却从未卖出的代币，是卖出被封锁的典型迹象。",
    "Legit projects usually list a website and social accounts on Dexscreener.": "正规项目通常会在 Dexscreener 列出网站和社交账号。",
    "How many wallets hold the token, and whether a few of them could dump on everyone else.": "有多少钱包持有，以及少数人是否可能对其他人砸盘。",
    "New tokens minted after launch dilute every holder.": "发行后增发的新代币会稀释所有持有人。",
    "Events read from the token's own on-chain history.": "从代币自身链上历史读取的事件。",
