    "Send one Arc token to many wallets at once — an airdrop, rewards, payroll in USDC. Paste a list, check it, approve once, and it goes out in as few transactions as possible, straight from your wallet.": "把一种 Arc 代币一次发给许多钱包 —— 空投、奖励、USDC 工资都可以。粘贴名单、检查、批准一次，就会直接从你的钱包以尽可能少的交易发出。",
    "Version 1 — new features are added regularly": "版本 1 —— 会持续加入新功能",
    "The Multisender contract isn't live on Arc yet. You can already load and check a list — sending switches on as soon as it's deployed.": "批量发送合约尚未在 Arc 上线。你现在就可以载入并检查名单 —— 合约部署后即可发送。",
