    "Couldn't list your positions right now.": "暂时无法列出你的仓位。",
    "pool": "池",
    "One project at a time. A 3-day USDC raise decides who leads it — and $ARCIRCLE holders vote on what it becomes, burning 1,000 $ARCIRCLE per vote.": "一次一个项目。3 天的 USDC 募集决定谁来领导——项目最终成为什么，由 $ARCIRCLE 持有者投票决定，每票销毁 1,000 枚 $ARCIRCLE。",
    "Name, ticker, logo and roadmap are all decided by $ARCIRCLE holders' votes once a raise closes — every vote burns 1,000 $ARCIRCLE. This card shows the shape of a round — it isn't a real one yet.": "募集结束后，名称、代码、Logo 和路线图全部由 $ARCIRCLE 持有者投票决定——每票销毁 1,000 枚 $ARCIRCLE。此卡片仅展示一轮的样子，并非真实轮次。",
    "Anyone holding $ARCIRCLE can vote — 1 vote = 1,000 $ARCIRCLE, burned.": "任何持有 $ARCIRCLE 的人都可以投票——1 票 = 销毁 1,000 枚 $ARCIRCLE。",
    "$ARCIRCLE holders vote on name, ticker, logo, roadmap, date — every vote burns 1,000 $ARCIRCLE.": "$ARCIRCLE 持有者对名称、代码、Logo、路线图和日期投票——每票销毁 1,000 枚 $ARCIRCLE。",
    "Anyone holding $ARCIRCLE can vote on the project's identity. Every vote costs 1,000 $ARCIRCLE, sent to the dead address (0x…dEaD) — burned for good, so every vote shrinks the supply. Vote as many times as you like; votes can't be changed or taken back. Five things get decided this way:": "任何持有 $ARCIRCLE 的人都可以对项目的身份投票。每票花费 1,000 枚 $ARCIRCLE，发送到销毁地址（0x…dEaD）永久销毁——每一票都会减少供应量。可以投任意多票；投票不能更改或撤回。以下五项由此决定：",
    "One project. A 3-day USDC raise decides who leads it and how it's split. $ARCIRCLE holders vote on what it becomes.": "一个项目。3 天的 USDC 募集决定谁来领导以及如何分配。项目最终成为什么，由 $ARCIRCLE 持有者投票决定。",
    "A single project raises USDC for 3 days on Arc. Every bid is recorded with the bidder's address and amount — this is what determines the final payout split.": "单个项目在 Arc 上募集 3 天 USDC。每笔出价都会记录出价者地址和金额——这决定最终的分配比例。",
    "Whoever bid the most becomes the project lead. The project's actual identity — coin name, ticker, logo, roadmap and launch date — is voted on by $ARCIRCLE holders: every vote burns 1,000 $ARCIRCLE.": "出价最多的人成为项目负责人。项目的实际身份——币名、代码、Logo、路线图和上线日期——由 $ARCIRCLE 持有者投票决定：每票销毁 1,000 枚 $ARCIRCLE。",
    "Yes — if the lead is ever marked abandoned, unvested funds return to all original bidders proportionally, not just the lead.": "是的——如果负责人被标记为放弃，未释放的资金会按比例退还给所有原始出价者，而不只是负责人。",
    "Candidates go up during the raise. Voting opens the moment it closes and runs for 48 hours: 1 vote = 1,000 $ARCIRCLE, burned for good.": "候选在募集期间发布。募集结束的那一刻投票开启，持续 48 小时：1 票 = 1,000 枚 $ARCIRCLE，永久销毁。",
    "Voting is open. Anyone holding $ARCIRCLE can vote — every vote burns 1,000 $ARCIRCLE.": "投票已开启。任何持有 $ARCIRCLE 的人都可以投票——每票销毁 1,000 枚 $ARCIRCLE。",
    "Voting opens as soon as the burn-vote contract is live.": "销毁投票合约上线后即开放投票。",
    "Candidates are up — voting opens at the close. 1 vote = 1,000 $ARCIRCLE burned.": "候选已发布——募集结束时开放投票。1 票 = 销毁 1,000 枚 $ARCIRCLE。",
    "Connect a wallet holding $ARCIRCLE to vote — 1 vote burns 1,000 $ARCIRCLE.": "连接持有 $ARCIRCLE 的钱包即可投票——每票销毁 1,000 枚 $ARCIRCLE。",
    "Hold $ARCIRCLE to vote: every 1,000 is one vote, burned when you cast it.": "持有 $ARCIRCLE 即可投票：每 1,000 枚为一票，投票时销毁。",
    "Each vote burns 1,000 $ARCIRCLE — it can't be changed or taken back.": "每票销毁 1,000 枚 $ARCIRCLE——不能更改或撤回。",
    "You need at least 1,000 $ARCIRCLE for one vote.": "一票至少需要 1,000 枚 $ARCIRCLE。",
