    "Every CirclePad round becomes a coin on Argus, and its first buy is relayed — to the round's contributors and to every wallet holding $ARCIRCLE. Keep holding $ARCIRCLE and you receive every relay: N+1, N+2, N+3 and on.": "每一轮 CirclePad 都会成为 Argus 上的代币，首笔买入会接力分发给本轮贡献者和所有持有 $ARCIRCLE 的钱包。持续持有 $ARCIRCLE，即可获得每一次接力：N+1、N+2、N+3……",
