    "Each side 0–10%, and not both 0. Argus fixes them at launch — nobody can change them later.": "每边 0–10%，不能都为 0。Argus 在发射时固定，之后任何人都无法更改。",
    "your four shares, after Argus's cut": "扣除 Argus 份额后的四项分配",
