    "A 7-day streak": "连续挖矿 7 天",
    "A mine runs 3–60 days in six equal layers. The first layer releases half of everything, so the earliest builders dig the richest ground. A top-up is released over what's left of the curve.": "一座矿运行 3–60 天，分为六层。第一层释放一半，所以最早的建造者挖到最富的矿。追加的存入会沿剩余曲线释放。",
    "A pickaxe is yours for good and works in every mine. An upgrade costs only the difference. Every $ARCIRCLE you pay is burned. Better pickaxes leave a trail when they strike.": "镐子永久归你，在所有矿场都能用。升级只需支付差价。支付的 $ARCIRCLE 全部销毁。越好的镐子挥击时会留下光轨。",
