    "Each hour's release is split by weight. Your browser does the hashing only while you press Start and the tab is open, and hands in its shares every 30 seconds.": "每小时的释放量按权重分配。只有点击开始且标签页打开时浏览器才计算哈希，每 30 秒提交一次份额。",
